const input = msg.payload || {};
const variants = Array.isArray(input.variants) ? input.variants : [];
const seen = new Set();
const items = [];
for (const variant of variants) {
  if (!variant || typeof variant !== 'object') continue;
  const id = typeof variant.id === 'string' ? variant.id.trim() : '';
  const title = typeof variant.title === 'string' ? variant.title.trim() : '';
  const image = typeof variant.image === 'string' ? variant.image.trim() : '';
  const description = typeof variant.description === 'string' ? variant.description.trim() : '';
  if (!id || !title || !/^data:image\/(png|jpeg|webp);base64,/i.test(image) || seen.has(id)) continue;
  seen.add(id);
  items.push({ id, title, ...(description ? { description } : {}), image });
}
if (!items.length) {
  msg.mcpResult = { content: [{ type: 'text', text: 'No valid image variants were provided.' }], isError: true };
  return msg;
}
msg.mcpElicitation = {
  mode: 'openai/form',
  message: typeof input.message === 'string' && input.message.trim() ? input.message.trim() : 'Choose one creative variant.',
  requestedSchema: {
    type: 'object',
    properties: {
      creative: { type: 'openai/imagePicker', title: 'Creative variant', items }
    },
    required: ['creative']
  }
};
return msg;
